-- Run in Supabase SQL Editor after replacing the email below everywhere.
create table if not exists public.entries(id bigint generated by default as identity primary key,title text not null check(char_length(title) between 1 and 100),excerpt text not null default '' check(char_length(excerpt)<=180),body text not null,image_url text,created_at timestamptz not null default now());
alter table public.entries enable row level security;
drop policy if exists "Public can read" on public.entries;
create policy "Public can read" on public.entries for select to anon,authenticated using(true);
drop policy if exists "Admin can insert" on public.entries;
create policy "Admin can insert" on public.entries for insert to authenticated with check((auth.jwt()->>'email')='REPLACE-WITH-YOUR-ADMIN-EMAIL@example.com');
drop policy if exists "Admin can update" on public.entries;
create policy "Admin can update" on public.entries for update to authenticated using((auth.jwt()->>'email')='REPLACE-WITH-YOUR-ADMIN-EMAIL@example.com') with check((auth.jwt()->>'email')='REPLACE-WITH-YOUR-ADMIN-EMAIL@example.com');
drop policy if exists "Admin can delete" on public.entries;
create policy "Admin can delete" on public.entries for delete to authenticated using((auth.jwt()->>'email')='REPLACE-WITH-YOUR-ADMIN-EMAIL@example.com');
-- Create the matching user manually in Supabase Authentication > Users. Disable public sign-ups.
